1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"errors"
17		"fmt"
18		"sort"
19		"strings"
20	)
21	
22	// SnapshotFormatVersion is the only on-disk snapshot format understood.
23	const SnapshotFormatVersion = 1
24	
25	// SnapshotFile is the on-disk representation of one frozen lineage graph.
26	//
27	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
28	// verified against Graph on every read; Graph carries the complete graph.
29	type SnapshotFile struct {
30		FormatVersion int       `json:"formatVersion"`
31		ContentID     string    `json:"contentId"`
32		Graph         GraphFile `json:"graph"`
33	}
34	
35	// RootSourceChange reports that one dataset present in BOTH versions reaches a
36	// different set of root sources. OldRoots and NewRoots are sorted by name and
37	// never nil, so empty root sets encode as [] rather than null.
38	type RootSourceChange struct {
39		Dataset  string   `json:"dataset"`
40		OldRoots []string `json:"oldRoots"`
41		NewRoots []string `json:"newRoots"`
42	}
43	
44	// CompareReport is the deterministic, read-only diff of two snapshots read in
45	// the fixed direction old -> new.
46	//
47	// NewDatasets and RemovedDatasets list nodes present on only one side.
48	// ChangedDatasets lists datasets present on both sides whose direct upstream
49	// set actually changed. AddedRelations and RemovedRelations list every
50	// directed edge present on only one side, including edges that vanish because
51	// one endpoint node was removed. RootSourceChanges covers only datasets common
52	// to both versions whose reachable root set differs; added or removed datasets
53	// never appear there.
54	type CompareReport struct {
55		NewDatasets       []string           `json:"newDatasets"`
56		RemovedDatasets   []string           `json:"removedDatasets"`
57		ChangedDatasets   []string           `json:"changedDatasets"`
58		AddedRelations    []Relation         `json:"addedRelations"`
59		RemovedRelations  []Relation         `json:"removedRelations"`
60		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
61	}
62	
63	// contentIDPrefix names the hash algorithm used for content addressing.
64	const contentIDPrefix = "sha256:"
65	
66	// canonicalGraph serializes the graph's semantics deterministically: datasets
67	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
68	// JSON with no insignificant whitespace. Two semantically equal graphs always
69	// produce identical bytes.
70	func canonicalGraph(adj adjacency) ([]byte, error) {
71		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
72		return json.Marshal(gf)
73	}
74	
75	// computeContentID returns the content identifier of the graph bytes:
76	// "sha256:" followed by the lowercase hex SHA-256 digest.
77	func computeContentID(canonical []byte) string {
78		sum := sha256.Sum256(canonical)
79		return contentIDPrefix + hex.EncodeToString(sum[:])
80	}
81	
82	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
83	// version 1 and the matching content identifier. It does not mutate graph. The
84	// returned document and its serialized bytes depend only on graph semantics.
85	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
86		if err := ValidateGraph(graph); err != nil {
87			return nil, err
88		}
89		adj, err := graphAdjacency(graph)
90		if err != nil {
91			return nil, err
92		}
93		canonical, err := canonicalGraph(adj)
94		if err != nil {
95			return nil, err
96		}
97		return &SnapshotFile{
98			FormatVersion: SnapshotFormatVersion,
99			ContentID:     computeContentID(canonical),
100			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
101		}, nil
102	}
103	
104	// MarshalSnapshot serializes a snapshot the same way for every save: indented
105	// JSON keyed by struct field order, terminated by a single newline.
106	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
107		var buf bytes.Buffer
108		enc := json.NewEncoder(&buf)
109		enc.SetIndent("", "  ")
110		enc.SetEscapeHTML(false)
111		if err := enc.Encode(snap); err != nil {
112			return nil, err
113		}
114		return buf.Bytes(), nil
115	}
116	
117	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
118	// can distinguish "field absent" from "field present with a zero value"
119	// (e.g. a missing formatVersion must be rejected rather than read as 0).
120	type rawSnapshot struct {
121		FormatVersion json.RawMessage `json:"formatVersion"`
122		ContentID     json.RawMessage `json:"contentId"`
123		Graph         json.RawMessage `json:"graph"`
124	}
125	
126	// isJSONNull reports whether a raw JSON value is the literal null.
127	func isJSONNull(raw json.RawMessage) bool {
128		return string(bytes.TrimSpace(raw)) == "null"
129	}
130	
131	// ParseSnapshot parses and strictly validates one snapshot document: required
132	// fields must be present and well-typed, no known field may be declared twice
133	// within the same object (even with identical values, a null first, or a
134	// spelling equivalent under Unicode case folding or JSON escaping), the
135	// format version must be supported, the embedded graph must be structurally
136	// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
137	// and the content identifier must correspond exactly to the graph. A
138	// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
139	// can never be trusted as a version.
140	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
141		if err := checkDuplicateFields(data); err != nil {
142			return nil, err
143		}
144		var raw rawSnapshot
145		if err := json.Unmarshal(data, &raw); err != nil {
146			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
147		}
148		if len(raw.FormatVersion) == 0 {
149			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
150		}
151		if len(raw.ContentID) == 0 {
152			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
153		}
154		if len(raw.Graph) == 0 {
155			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
156		}
157		// An explicit JSON null is present-but-untyped and must not be silently
158		// treated as a zero value (in particular, graph:null must not read as an
159		// empty graph).
160		if isJSONNull(raw.FormatVersion) {
161			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
162		}
163		if isJSONNull(raw.ContentID) {
164			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
165		}
166		if isJSONNull(raw.Graph) {
167			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
168		}
169	
170		var version int
171		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
172			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
173		}
174		if version != SnapshotFormatVersion {
175			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
176		}
177	
178		var contentID string
179		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
180			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
181		}
182		if contentID == "" {
183			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
184		}
185	
186		var gf GraphFile
187		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
188			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
189		}
190		// The embedded graph obeys exactly the same structural rules as a
191		// standalone graph file, so the two readers can never judge one graph
192		// differently.
193		adj, err := validateGraphStructureFromFile(gf.Datasets)
194		if err != nil {
195			return nil, err
196		}
197	
198		canonical, err := canonicalGraph(adj)
199		if err != nil {
200			return nil, err
201		}
202		if want := computeContentID(canonical); contentID != want {
203			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
204		}
205	
206		return &SnapshotFile{
207			FormatVersion: version,
208			ContentID:     contentID,
209			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
210		}, nil
211	}
212	
213	// errAbortScan stops the duplicate-field scan when the document is too
214	// malformed to keep walking; the regular parse then reports the syntax or
215	// type error instead.
216	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
217	
218	// checkDuplicateFields rejects a snapshot in which a known field is declared
219	// more than once within the same object: formatVersion, contentId, and graph
220	// at the top level, datasets inside graph, and name and upstreams inside each
221	// dataset record. A repeated field is ambiguous — the reader would silently
222	// keep only one declaration — so the whole snapshot is refused even when the
223	// duplicates carry identical values, the first is null, or the surviving value
224	// would pass every other check.
225	//
226	// The decoder uses UseNumber so numbers are kept verbatim instead of being
227	// converted to float64: a perfectly legal JSON number outside the float64
228	// range (such as 1e400), even one buried in an ignored unknown field's value,
229	// must not make the decoder error out and abort the whole scan — otherwise an
230	// unrelated large number placed before a repeated known field would hide that
231	// duplication. Malformed number syntax still fails and is left to the regular
232	// parse to report.
233	//
234	// Field names are compared after JSON string unescaping and with the same
235	// Unicode simple case-folding the decoder applies to its case-insensitive
236	// field lookup (equivalent to strings.EqualFold), so "name", "Name", and
237	// "name" all collide, and so do spellings that only differ in a fold
238	// equivalent rune such as "formatVerſion" (long s) and "formatVersion".
239	// Unknown fields keep their ignore-everything behavior and may repeat freely.
240	// Documents that are not shaped like a snapshot at all are left to the
241	// regular parse, which reports the structural problem.
242	func checkDuplicateFields(data []byte) error {
243		dec := json.NewDecoder(bytes.NewReader(data))
244		dec.UseNumber()
245		err := checkTopLevelObject(dec)
246		if errors.Is(err, errAbortScan) {
247			return nil
248		}
249		return err
250	}
251	
252	// checkTopLevelObject scans the top-level snapshot object for repeated
253	// formatVersion/contentId/graph declarations, descending into graph values.
254	func checkTopLevelObject(dec *json.Decoder) error {
255		tok, err := scanToken(dec)
256		if err != nil {
257			return err
258		}
259		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
260			return nil // not an object: the regular parse reports the type error
261		}
262		seen := make(map[string]bool, 3)
263		for dec.More() {
264			key, err := scanKey(dec)
265			if err != nil {
266				return err
267			}
268			field, known := snapshotField(key)
269			if known {
270				if seen[field] {
271					return duplicateFieldError(field, "at the top level of the snapshot")
272				}
273				seen[field] = true
274			}
275			if field == "graph" {
276				if err := checkGraphValue(dec); err != nil {
277					return err
278				}
279			} else if err := skipValue(dec); err != nil {
280				return err
281			}
282		}
283		_, err = scanToken(dec) // closing '}'
284		return err
285	}
286	
287	// checkGraphValue scans one graph value for a repeated datasets declaration,
288	// descending into each dataset record of the datasets array.
289	func checkGraphValue(dec *json.Decoder) error {
290		tok, err := scanToken(dec)
291		if err != nil {
292			return err
293		}
294		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
295			// Not an object (null, array, scalar): consume any remainder and let
296			// the regular parse report the type problem.
297			return skipRest(dec, tok)
298		}
299		seen := false
300		for dec.More() {
301			key, err := scanKey(dec)
302			if err != nil {
303				return err
304			}
305			if strings.EqualFold(key, "datasets") {
306				if seen {
307					return duplicateFieldError("datasets", `in "graph"`)
308				}
309				seen = true
310				if err := checkDatasetsValue(dec); err != nil {
311					return err
312				}
313			} else if err := skipValue(dec); err != nil {
314				return err
315			}
316		}
317		_, err = scanToken(dec) // closing '}'
318		return err
319	}
320	
321	// checkDatasetsValue scans one datasets array, checking every record that is
322	// an object for repeated name/upstreams declarations.
323	func checkDatasetsValue(dec *json.Decoder) error {
324		tok, err := scanToken(dec)
325		if err != nil {
326			return err
327		}
328		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
329			return skipRest(dec, tok) // not an array: the regular parse reports it
330		}
331		for index := 0; dec.More(); index++ {
332			if err := checkDatasetRecord(dec, index); err != nil {
333				return err
334			}
335		}
336		_, err = scanToken(dec) // closing ']'
337		return err
338	}
339	
340	// checkDatasetRecord scans one element of the datasets array. If it is an
341	// object, name and upstreams must each be declared at most once.
342	func checkDatasetRecord(dec *json.Decoder, index int) error {
343		tok, err := scanToken(dec)
344		if err != nil {
345			return err
346		}
347		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
348			return skipRest(dec, tok) // not an object: the regular parse reports it
349		}
350		seen := make(map[string]bool, 2)
351		for dec.More() {
352			key, err := scanKey(dec)
353			if err != nil {
354				return err
355			}
356			if field, known := datasetField(key); known {
357				if seen[field] {
358					return duplicateFieldError(field, fmt.Sprintf("in the dataset record at index %d of \"datasets\"", index))
359				}
360				seen[field] = true
361			}
362			if err := skipValue(dec); err != nil {
363				return err
364			}
365		}
366		_, err = scanToken(dec) // closing '}'
367		return err
368	}
369	
370	// duplicateFieldError reports a known field declared twice, naming the field
371	// and where in the document the repetition occurred.
372	func duplicateFieldError(field, location string) error {
373		return fmt.Errorf("%w: field %q is declared more than once %s", ErrInvalidArgument, field, location)
374	}
375	
376	// snapshotField maps a top-level key to the canonical name of the snapshot
377	// field it selects, matching the decoder's case-insensitive field lookup.
378	func snapshotField(key string) (string, bool) {
379		switch {
380		case strings.EqualFold(key, "formatVersion"):
381			return "formatVersion", true
382		case strings.EqualFold(key, "contentId"):
383			return "contentId", true
384		case strings.EqualFold(key, "graph"):
385			return "graph", true
386		}
387		return "", false
388	}
389	
390	// datasetField maps a dataset-record key to the canonical name of the record
391	// field it selects, matching the decoder's case-insensitive field lookup.
392	func datasetField(key string) (string, bool) {
393		switch {
394		case strings.EqualFold(key, "name"):
395			return "name", true
396		case strings.EqualFold(key, "upstreams"):
397			return "upstreams", true
398		}
399		return "", false
400	}
401	
402	// scanToken reads one token; any decode failure aborts the scan so the
403	// regular parse can report the malformed document.
404	func scanToken(dec *json.Decoder) (json.Token, error) {
405		tok, err := dec.Token()
406		if err != nil {
407			return nil, errAbortScan
408		}
409		return tok, nil
410	}
411	
412	// scanKey reads the next key of the object currently being walked.
413	func scanKey(dec *json.Decoder) (string, error) {
414		tok, err := scanToken(dec)
415		if err != nil {
416			return "", err
417		}
418		key, ok := tok.(string)
419		if !ok {
420			return "", errAbortScan
421		}
422		return key, nil
423	}
424	
425	// skipValue consumes one complete JSON value.
426	func skipValue(dec *json.Decoder) error {
427		tok, err := scanToken(dec)
428		if err != nil {
429			return err
430		}
431		return skipRest(dec, tok)
432	}
433	
434	// skipRest consumes the remainder of a value whose first token is tok.
435	func skipRest(dec *json.Decoder, tok json.Token) error {
436		delim, ok := tok.(json.Delim)
437		if !ok {
438			return nil // scalar, fully consumed already
439		}
440		var closer json.Delim
441		switch delim {
442		case '{':
443			closer = '}'
444			for dec.More() {
445				if _, err := scanKey(dec); err != nil {
446					return err
447				}
448				if err := skipValue(dec); err != nil {
449					return err
450				}
451			}
452		case '[':
453			closer = ']'
454			for dec.More() {
455				if err := skipValue(dec); err != nil {
456					return err
457				}
458			}
459		default:
460			return errAbortScan
461		}
462		tok, err := scanToken(dec)
463		if err != nil {
464			return err
465		}
466		if end, ok := tok.(json.Delim); !ok || end != closer {
467			return errAbortScan
468		}
469		return nil
470	}
471	
472	// CompareSnapshots returns the fixed-direction diff from old to new. Both
473	// inputs are assumed to have passed ParseSnapshot; the report is fully
474	// deterministic and identical for semantically identical comparisons.
475	func CompareSnapshots(oldSnap, newSnap *SnapshotFile) *CompareReport {
476		oldAdj := adjacencyFromValidFile(oldSnap.Graph)
477		newAdj := adjacencyFromValidFile(newSnap.Graph)
478	
479		added, removed := diffRelations(oldAdj, newAdj)
480	
481		var newNodes, removedNodes, changedNodes []string
482		for name := range newAdj {
483			if oldParents, ok := oldAdj[name]; !ok {
484				newNodes = append(newNodes, name)
485			} else if !stringSliceEqual(oldParents, newAdj[name]) {
486				changedNodes = append(changedNodes, name)
487			}
488		}
489		for name := range oldAdj {
490			if _, ok := newAdj[name]; !ok {
491				removedNodes = append(removedNodes, name)
492			}
493		}
494		sort.Strings(newNodes)
495		sort.Strings(removedNodes)
496		sort.Strings(changedNodes)
497	
498		common := make([]string, 0)
499		for name := range oldAdj {
500			if _, ok := newAdj[name]; ok {
501				common = append(common, name)
502			}
503		}
504		sort.Strings(common)
505	
506		rootChanges := make([]RootSourceChange, 0)
507		for _, name := range common {
508			oldRoots := rootSources(name, oldAdj)
509			newRoots := rootSources(name, newAdj)
510			if !stringSliceEqual(oldRoots, newRoots) {
511				rootChanges = append(rootChanges, RootSourceChange{
512					Dataset:  name,
513					OldRoots: oldRoots,
514					NewRoots: newRoots,
515				})
516			}
517		}
518	
519		return &CompareReport{
520			NewDatasets:       orEmptyStrings(newNodes),
521			RemovedDatasets:   orEmptyStrings(removedNodes),
522			ChangedDatasets:   orEmptyStrings(changedNodes),
523			AddedRelations:    orEmptyRelations(added),
524			RemovedRelations:  orEmptyRelations(removed),
525			RootSourceChanges: rootChanges,
526		}
527	}
528	
529	// adjacencyFromValidFile builds normalized parent adjacency from an already
530	// validated graph file.
531	func adjacencyFromValidFile(gf GraphFile) adjacency {
532		adj := make(adjacency, len(gf.Datasets))
533		for _, ds := range gf.Datasets {
534			adj[ds.Name] = uniqueSorted(ds.Upstreams)
535		}
536		return adj
537	}
538	
539	// rootSources returns the root datasets reachable from node by following
540	// direct upstream edges. A node without upstreams is itself a root and its own
541	// source, so it is included. Nodes reached by more than one path count once.
542	// The result is sorted by name and never nil.
543	func rootSources(node string, adj adjacency) []string {
544		visited := make(map[string]bool)
545		var roots []string
546		var walk func(string)
547		walk = func(current string) {
548			if visited[current] {
549				return
550			}
551			visited[current] = true
552			parents := adj[current]
553			if len(parents) == 0 {
554				roots = append(roots, current)
555				return
556			}
557			for _, parent := range parents {
558				walk(parent)
559			}
560		}
561		walk(node)
562		sort.Strings(roots)
563		return orEmptyStrings(roots)
564	}
565	
566	func orEmptyStrings(s []string) []string {
567		if s == nil {
568			return []string{}
569		}
570		return s
571	}
572	
573	func orEmptyRelations(r []Relation) []Relation {
574		if r == nil {
575			return []Relation{}
576		}
577		return r
578	}
